'use client';

import { useMemo } from "react";
import { createStyles } from "../../core/style";
import { Selectors } from "../../types";
import { classes, combineClasses } from "../../utils";
import { random, hash } from "../../core/utils";
import { useSingleton } from "../../context/singletons";

const noiseImage = `url("data:image/png;base64,")`;

const styles = createStyles('gradient', {
    '.gradient': {
        background: 'var(--background, var(--f-clr-grey-500))',
        overflow: 'hidden'
    },

    '.mesh': {
        width: '100%',
        height: '100%',
        background: 'var(--background)',
        willChange: 'transform'
    },

    '.noise': {
        position: 'absolute',
        width: 'inherit',
        height: 'inherit',
        pointerEvents: 'none',
        backgroundRepeat: 'repeat',
        backgroundSize: '96px 96px',
        mixBlendMode: 'overlay',
        zIndex: 1
    }
});

export type GradientSelectors = Selectors<'gradient' | 'mesh' | 'noise'>;

/**
 * An easy beautiful gradient.
 * 
 * @see {@link https://fluid.infinityfx.dev/docs/components/gradient}
 */
export default function Gradient({ cc = {}, stops, type = 'linear', angle = 0, noise = .05, meshSeed = 'fluid', warp = 0, warpScale = 1, ...props }: {
    ref?: React.Ref<HTMLDivElement>;
    cc?: GradientSelectors;
    stops: string[];
    type?: 'linear' | 'radial' | 'mesh';
    /**
     * The gradient angle in degrees.
     */
    angle?: number;
    /**
     * @default 0.05
     */
    noise?: number;
    /**
     * A random string used to generate mesh gradient positions.
     * 
     * The same seed will always give the same mesh gradient result.
     * 
     * @default fluid
     */
    meshSeed?: string;
    /**
     * Apply warping to mesh gradients.
     * 
     * Only takes effect when `type` = `'mesh'`
     * 
     * @default 0
     */
    warp?: number;
    /**
     * @default 1
     */
    warpScale?: number;
} & React.HTMLAttributes<HTMLDivElement>) {
    const style = combineClasses(styles, cc);

    const warpId = `${meshSeed}-${warp.toFixed(2)}-${warpScale.toFixed(2)}`;
    const shouldRender = useSingleton(warpId);

    const overlapScale = 1 + warp * 0.45;
    const gradient = useMemo(() => {
        switch (type) {
            case 'linear':
                return `linear-gradient(in oklab ${angle}deg, ${stops.join(', ')})`;
            case 'radial':
                return `radial-gradient(in oklab, ${stops.join(', ')})`;
            case 'mesh':
                return stops.toReversed().map((stop, i) => {
                    if (i === stops.length - 1) return `linear-gradient(${stop}, ${stop})`;

                    const x = .5 + (random(meshSeed + i) - .5) / overlapScale;
                    const y = .5 + (random('' + x) - .5) / overlapScale;

                    return `radial-gradient(circle at ${Math.round(x * 100)}% ${Math.round(y * 100)}%, ${stop}, transparent ${Math.round(40 + 1 / (stops.length - i - 1) * 60) / overlapScale}%)`
                }).join(', ');
        }
    }, [type, stops, meshSeed, overlapScale]);

    return <div
        {...props}
        className={classes(props.className, style.gradient)}
        style={{
            ...props.style,
            '--background': gradient
        } as any}>
        {noise ? <div
            className={style.noise}
            style={{
                opacity: noise,
                backgroundImage: noiseImage // todo: optimize (maybe use singleton provider?)
            }} /> : null}
        {type === 'mesh' && <div
            className={style.mesh}
            style={{
                scale: overlapScale,
                filter: `blur(32px) ${warp ? `url(#df-${warpId}) blur(2px)` : ''} brightness(.92) contrast(1.6)`
            }} />}

        {shouldRender() && <svg style={{ position: 'absolute', width: 0, height: 0 }}>
            <defs>
                <filter x="-25%" y="-25%" width="150%" height="150%" id={`df-${warpId}`} colorInterpolationFilters="sRGB">
                    <feTurbulence type="fractalNoise" seed={hash(meshSeed).toString().slice(0, 5)} baseFrequency={.005 / Math.max(warpScale, 0.01)} numOctaves={1} result="noise" />
                    <feDisplacementMap in="SourceGraphic" in2="noise" scale={warp * 200} xChannelSelector="R" yChannelSelector="R" />
                </filter>
            </defs>
        </svg>}
    </div>;
}